test("permission events preserve canonical workspace and structured risk", () => {
  useSessionStore.getState().apply({
    type: "permission_changed",
    runId: "run-1",
    eventSeq: 1,
    permissionId: "permission-1",
    toolName: "shell",
    arguments: { command: "git status" },
    workspace: { workspaceId: "workspace-1", generation: 4 },
    risk: { level: "high", reason: "workspace-default" },
    revision: 3,
    status: "pending",
  })

  expect(useSessionStore.getState().permission).toEqual({
    id: "permission-1",
    tool: "shell",
    arguments: { command: "git status" },
    workspace: { workspaceId: "workspace-1", generation: 4 },
    risk: { level: "high", reason: "workspace-default" },
    revision: 3,
  })
})

